python3 -c "
import re

# Let me get all the Commerce values from the 2024 bulletin for FY2016-2024
# The key is to find the fiscal year rows (e.g., '| 2020 |')

with open('/app/resources/treasury_bulletin_2024_12.txt', 'r') as f:
    content = f.read()

# Find lines with fiscal years for Commerce - column 4
lines = content.split('\n')
commerce_data = {}

for line in lines:
    # Match lines like '| 2020 |' at the start
    match = re.match(r'\|\s*(201[6-9]|202[0-4])\s*\|', line)
    if match and 'Department of Commerce' not in line:
        parts = line.split('|')
        # Column 4 is Department of Commerce (after empty, Legislative, Judicial, Agriculture)
        if len(parts) > 4:
            try:
                year = int(match.group(1))
                val = parts[4].strip()
                if val and val != '' and val != 'nan':
                    # Remove any commas and convert
                    val_clean = val.replace(',', '').replace('.', '')
                    if val_clean.replace('-', '').isdigit():
                        commerce_data[year] = int(val_clean)
            except:
                pass

print('From 2024 bulletin - Commerce outlays by year:')
for year in sorted(commerce_data.keys()):
    print(f'{year}: {commerce_data[year]}')
"

