python3 -c "
import re

# Correct data extraction for Department of Commerce total outlays
# From 2020 bulletin (2016-2020) and 2024 bulletin (2020-2024)

# From 2020 bulletin
with open('/app/resources/treasury_bulletin_2020_12.txt', 'r') as f:
    content = f.read()

lines = content.split('\n')
commerce_2016_2020 = {}

# Find the FFO-3 table header
for i, line in enumerate(lines):
    if 'Department of Commerce (4)' in line:
        # Found header, now get data for 2016-2020
        for j in range(i+2, i+10):  # Look at next few lines
            parts = lines[j].split('|')
            if len(parts) > 5:
                try:
                    year_str = parts[1].strip()
                    if re.match(r'201[6-9]', year_str):
                        year = int(year_str)
                        val = parts[5].strip().replace(',', '')
                        if val != '-' and val != '*':
                            commerce_2016_2020[year] = int(val)
                    elif year_str == '2020':
                        year = 2020
                        val = parts[5].strip().replace(',', '')
                        if val != '-' and val != '*':
                            commerce_2016_2020[year] = int(val)
                except:
                    pass
        break

# From 2024 bulletin 
with open('/app/resources/treasury_bulletin_2024_12.txt', 'r') as f:
    content = f.read()

lines = content.split('\n')
commerce_2020_2024 = {}

for i, line in enumerate(lines):
    if 'Department of Commerce (4)' in line:
        for j in range(i+2, i+10):
            parts = lines[j].split('|')
            if len(parts) > 5:
                try:
                    year_str = parts[1].strip()
                    if re.match(r'202[0-4]', year_str) and 'Est' not in year_str:
                        year = int(year_str)
                        val = parts[5].strip().replace(',', '')
                        if val != '-' and val != '*':
                            commerce_2020_2024[year] = int(val)
                except:
                    pass
        break

# Combine and print
print('Department of Commerce Total Outlays (millions):')
all_commerce = {**commerce_2016_2020, **commerce_2020_2024}
for year in sorted(all_commerce.keys()):
    print(f'FY {year}: {all_commerce[year]}')
"
